CREATE TABLE IF NOT EXISTS "players" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Character name shown in the world. Unique per shard in this model.
	"username" VARCHAR(32) NOT NULL UNIQUE,
	-- Shard the character lives on. Items never cross realms without an explicit transfer.
	"realm_code" VARCHAR(24) NOT NULL,
	-- Current character level. Gates which templates can be equipped.
	"level" SMALLINT NOT NULL DEFAULT 1,
	-- Capacity of the built-in backpack, which is not a bag item and so has no container row of its own to resize.
	"backpack_slots" SMALLINT NOT NULL DEFAULT 16,
	-- Character creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last logout. Drives mail expiry grace periods for inactive accounts.
	"last_seen_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "players" IS 'A character that can hold items. Everything in this schema hangs off a character rather than an account, because inventory in most MMOs is per-character and only the bank is shared.';
COMMENT ON COLUMN "players"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "players"."username" IS 'Character name shown in the world. Unique per shard in this model.';
COMMENT ON COLUMN "players"."realm_code" IS 'Shard the character lives on. Items never cross realms without an explicit transfer.';
COMMENT ON COLUMN "players"."level" IS 'Current character level. Gates which templates can be equipped.';
COMMENT ON COLUMN "players"."backpack_slots" IS 'Capacity of the built-in backpack, which is not a bag item and so has no container row of its own to resize.';
COMMENT ON COLUMN "players"."created_at" IS 'Character creation time.';
COMMENT ON COLUMN "players"."last_seen_at" IS 'Last logout. Drives mail expiry grace periods for inactive accounts.';

CREATE TABLE IF NOT EXISTS "item_templates" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable content key from the game data files, e.g. sword_ashbringer. Designers reference this, never the numeric id.
	"code" VARCHAR(64) NOT NULL UNIQUE,
	-- Display name before affixes are appended.
	"name" VARCHAR(120) NOT NULL,
	-- weapon | armor | consumable | material | quest | container.
	"item_class" VARCHAR(32) NOT NULL,
	-- head | chest | main_hand | off_hand | trinket. Null for anything that cannot be equipped.
	"equip_slot" VARCHAR(32),
	-- common | uncommon | rare | epic | legendary. Drives the affix budget and the name colour.
	"quality" VARCHAR(20) NOT NULL DEFAULT 'common',
	-- Power tier. Combined with quality it sets the roll ranges for affixes.
	"item_level" INTEGER NOT NULL DEFAULT 1,
	-- Character level needed to equip or use the item.
	"required_level" SMALLINT NOT NULL DEFAULT 1,
	-- How many units one slot may hold. 1 means unstackable, which is what every item with per-instance state must be.
	"max_stack" INTEGER NOT NULL DEFAULT 1,
	-- Full durability for gear. Null for items that never wear out.
	"max_durability" INTEGER,
	-- none | on_pickup | on_equip | on_use. Determines when an instance becomes soulbound and stops being tradable.
	"bind_rule" VARCHAR(24) NOT NULL DEFAULT 'none',
	-- Upper bound on rolled affixes. Zero for materials and consumables, which is why they can stack.
	"max_affixes" SMALLINT NOT NULL DEFAULT 0,
	-- NPC sell value in the smallest currency unit. Integer only, never float.
	"vendor_price_copper" INTEGER NOT NULL DEFAULT 0,
	-- Blocks equipping a second copy. Enforced in game logic; the database cannot see equipped state cheaply.
	"is_unique_equipped" BOOLEAN NOT NULL DEFAULT false,
	-- When the template was first published by a content patch.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "item_templates" IS 'The design of an item: what a sword is. It is reference data shipped with the game build, shared by every copy in the world, and it holds no ownership, no durability and no stack count.';
COMMENT ON COLUMN "item_templates"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "item_templates"."code" IS 'Stable content key from the game data files, e.g. sword_ashbringer. Designers reference this, never the numeric id.';
COMMENT ON COLUMN "item_templates"."name" IS 'Display name before affixes are appended.';
COMMENT ON COLUMN "item_templates"."item_class" IS 'weapon | armor | consumable | material | quest | container.';
COMMENT ON COLUMN "item_templates"."equip_slot" IS 'head | chest | main_hand | off_hand | trinket. Null for anything that cannot be equipped.';
COMMENT ON COLUMN "item_templates"."quality" IS 'common | uncommon | rare | epic | legendary. Drives the affix budget and the name colour.';
COMMENT ON COLUMN "item_templates"."item_level" IS 'Power tier. Combined with quality it sets the roll ranges for affixes.';
COMMENT ON COLUMN "item_templates"."required_level" IS 'Character level needed to equip or use the item.';
COMMENT ON COLUMN "item_templates"."max_stack" IS 'How many units one slot may hold. 1 means unstackable, which is what every item with per-instance state must be.';
COMMENT ON COLUMN "item_templates"."max_durability" IS 'Full durability for gear. Null for items that never wear out.';
COMMENT ON COLUMN "item_templates"."bind_rule" IS 'none | on_pickup | on_equip | on_use. Determines when an instance becomes soulbound and stops being tradable.';
COMMENT ON COLUMN "item_templates"."max_affixes" IS 'Upper bound on rolled affixes. Zero for materials and consumables, which is why they can stack.';
COMMENT ON COLUMN "item_templates"."vendor_price_copper" IS 'NPC sell value in the smallest currency unit. Integer only, never float.';
COMMENT ON COLUMN "item_templates"."is_unique_equipped" IS 'Blocks equipping a second copy. Enforced in game logic; the database cannot see equipped state cheaply.';
COMMENT ON COLUMN "item_templates"."created_at" IS 'When the template was first published by a content patch.';

CREATE INDEX "idx_templates_class_level"
ON "item_templates" ("item_class", "item_level");
CREATE INDEX "idx_templates_quality"
ON "item_templates" ("quality");

CREATE TABLE IF NOT EXISTS "item_instances" (
	-- Surrogate primary key. This number is the item as far as players, logs and support tickets are concerned.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Which design this is a copy of. Immutable for the life of the instance.
	"template_id" BIGINT NOT NULL,
	-- Current owner. Null while the item sits in trade escrow, in undelivered mail, or on a corpse in the world.
	"owner_player_id" BIGINT,
	-- Units in this stack. Always 1 for anything with affixes or durability, because those are per-instance facts a stack cannot share.
	"stack_count" INTEGER NOT NULL DEFAULT 1,
	-- Remaining durability. Null when the template has none.
	"durability_current" INTEGER,
	-- Soulbound owner. Once set, the item can never be traded or mailed again, even back to the player who gave it away.
	"bound_to_player_id" BIGINT,
	-- When binding happened. Kept because support needs to prove the item was still tradable at the time of a disputed trade.
	"bound_at" TIMESTAMP,
	-- RNG seed the affix roll came from. Storing it means a roll can be reproduced and audited without trusting the rolled rows.
	"affix_seed" BIGINT,
	-- When the item entered the world.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft delete. Rows are never hard-deleted so a rollback can resurrect an item without inventing a new id.
	"destroyed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "item_instances" IS 'One physical item in the world: your sword, with your durability and your rolled stats. The split from item_templates is the whole design - a million players holding the same sword share one template row and own a million instance rows.';
COMMENT ON COLUMN "item_instances"."id" IS 'Surrogate primary key. This number is the item as far as players, logs and support tickets are concerned.';
COMMENT ON COLUMN "item_instances"."template_id" IS 'Which design this is a copy of. Immutable for the life of the instance.';
COMMENT ON COLUMN "item_instances"."owner_player_id" IS 'Current owner. Null while the item sits in trade escrow, in undelivered mail, or on a corpse in the world.';
COMMENT ON COLUMN "item_instances"."stack_count" IS 'Units in this stack. Always 1 for anything with affixes or durability, because those are per-instance facts a stack cannot share.';
COMMENT ON COLUMN "item_instances"."durability_current" IS 'Remaining durability. Null when the template has none.';
COMMENT ON COLUMN "item_instances"."bound_to_player_id" IS 'Soulbound owner. Once set, the item can never be traded or mailed again, even back to the player who gave it away.';
COMMENT ON COLUMN "item_instances"."bound_at" IS 'When binding happened. Kept because support needs to prove the item was still tradable at the time of a disputed trade.';
COMMENT ON COLUMN "item_instances"."affix_seed" IS 'RNG seed the affix roll came from. Storing it means a roll can be reproduced and audited without trusting the rolled rows.';
COMMENT ON COLUMN "item_instances"."created_at" IS 'When the item entered the world.';
COMMENT ON COLUMN "item_instances"."destroyed_at" IS 'Soft delete. Rows are never hard-deleted so a rollback can resurrect an item without inventing a new id.';

CREATE INDEX "idx_instances_owner_template"
ON "item_instances" ("owner_player_id", "template_id");
CREATE INDEX "idx_instances_template"
ON "item_instances" ("template_id");
CREATE INDEX "idx_instances_destroyed"
ON "item_instances" ("destroyed_at");

CREATE TABLE IF NOT EXISTS "affix_definitions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Content key, e.g. of_the_bear. Used by designers and by the client to look up wording.
	"code" VARCHAR(64) NOT NULL UNIQUE,
	-- Text stitched into the item name, e.g. Flaming or of the Bear. Prefix or suffix decided by placement.
	"display_fragment" VARCHAR(60) NOT NULL,
	-- prefix | suffix | enchant. Prefix and suffix roll at drop time; enchant is applied later by a player.
	"placement" VARCHAR(16) NOT NULL,
	-- Stat modified, e.g. strength or crit_rating. Kept as a key rather than a column so a new stat needs no migration.
	"stat_key" VARCHAR(40) NOT NULL,
	-- Lower bound of the roll at item_level 1.
	"min_value" NUMERIC(10,2) NOT NULL,
	-- Upper bound of the roll at item_level 1. Scaled by the instance item level when rolled.
	"max_value" NUMERIC(10,2) NOT NULL,
	-- Restricts the affix to one class of item. Null means it can appear on anything.
	"allowed_item_class" VARCHAR(32),
	-- Affix does not appear below this item level, which is how loot tiers stay distinct.
	"min_item_level" INTEGER NOT NULL DEFAULT 1,
	-- Relative selection weight in the roll table. Rarer affixes carry a smaller weight.
	"weight" INTEGER NOT NULL DEFAULT 100,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "affix_definitions" IS 'The pool of modifiers an item can roll. This is content data like item_templates, not player data, and the roll ranges live here so a balance patch reshapes future drops without touching existing instances.';
COMMENT ON COLUMN "affix_definitions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "affix_definitions"."code" IS 'Content key, e.g. of_the_bear. Used by designers and by the client to look up wording.';
COMMENT ON COLUMN "affix_definitions"."display_fragment" IS 'Text stitched into the item name, e.g. Flaming or of the Bear. Prefix or suffix decided by placement.';
COMMENT ON COLUMN "affix_definitions"."placement" IS 'prefix | suffix | enchant. Prefix and suffix roll at drop time; enchant is applied later by a player.';
COMMENT ON COLUMN "affix_definitions"."stat_key" IS 'Stat modified, e.g. strength or crit_rating. Kept as a key rather than a column so a new stat needs no migration.';
COMMENT ON COLUMN "affix_definitions"."min_value" IS 'Lower bound of the roll at item_level 1.';
COMMENT ON COLUMN "affix_definitions"."max_value" IS 'Upper bound of the roll at item_level 1. Scaled by the instance item level when rolled.';
COMMENT ON COLUMN "affix_definitions"."allowed_item_class" IS 'Restricts the affix to one class of item. Null means it can appear on anything.';
COMMENT ON COLUMN "affix_definitions"."min_item_level" IS 'Affix does not appear below this item level, which is how loot tiers stay distinct.';
COMMENT ON COLUMN "affix_definitions"."weight" IS 'Relative selection weight in the roll table. Rarer affixes carry a smaller weight.';

CREATE INDEX "idx_affixes_placement_class"
ON "affix_definitions" ("placement", "allowed_item_class");

CREATE TABLE IF NOT EXISTS "item_affixes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instance the modifier is attached to.
	"item_instance_id" BIGINT NOT NULL,
	-- Which modifier rolled.
	"affix_definition_id" BIGINT NOT NULL,
	-- Ordinal position on the item. Enchants usually occupy a fixed high slot so they can be replaced independently.
	"slot_index" SMALLINT NOT NULL,
	-- The actual number this copy got, frozen at roll time. Rebalancing the definition later must not silently change an item a player already owns.
	"rolled_value" NUMERIC(10,2) NOT NULL,
	-- When the modifier landed. Drop-time affixes share the instance creation time; enchants do not.
	"applied_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- drop | enchanter | reforge | gm. Explains where a modifier came from during an investigation.
	"applied_by" VARCHAR(24) NOT NULL DEFAULT 'drop',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "item_affixes" IS 'The rolled modifiers on one instance. Rows rather than columns, because the number of affixes varies by quality and a fixed affix1..affix6 layout makes every stat query a six-way OR.';
COMMENT ON COLUMN "item_affixes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "item_affixes"."item_instance_id" IS 'Instance the modifier is attached to.';
COMMENT ON COLUMN "item_affixes"."affix_definition_id" IS 'Which modifier rolled.';
COMMENT ON COLUMN "item_affixes"."slot_index" IS 'Ordinal position on the item. Enchants usually occupy a fixed high slot so they can be replaced independently.';
COMMENT ON COLUMN "item_affixes"."rolled_value" IS 'The actual number this copy got, frozen at roll time. Rebalancing the definition later must not silently change an item a player already owns.';
COMMENT ON COLUMN "item_affixes"."applied_at" IS 'When the modifier landed. Drop-time affixes share the instance creation time; enchants do not.';
COMMENT ON COLUMN "item_affixes"."applied_by" IS 'drop | enchanter | reforge | gm. Explains where a modifier came from during an investigation.';

CREATE UNIQUE INDEX "uq_item_affixes_instance_slot"
ON "item_affixes" ("item_instance_id", "slot_index");
CREATE INDEX "idx_item_affixes_definition"
ON "item_affixes" ("affix_definition_id");

CREATE TABLE IF NOT EXISTS "containers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Character the container belongs to.
	"owner_player_id" BIGINT NOT NULL,
	-- backpack | bag | bank | equipped | buyback | guild_bank. Equipped is modelled as a container so gear obeys the same one-item-one-place rule.
	"kind" VARCHAR(24) NOT NULL,
	-- Which bag position this container occupies on the character. Zero for the backpack and the equipped set.
	"bag_slot" SMALLINT NOT NULL DEFAULT 0,
	-- The bag item that provides the space. Null for the backpack, the bank and the equipped set, which exist without an item.
	"bag_item_instance_id" BIGINT,
	-- Number of usable positions. Copied from the bag template so resizing a bag design does not retroactively drop items on the floor.
	"capacity" SMALLINT NOT NULL,
	-- When the container was opened or the bag equipped.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "containers" IS 'Any space that can hold items. Treating bags, the bank and the equipment sheet as one concept means moving a helmet from the head slot into the bank is a single update rather than three special cases.';
COMMENT ON COLUMN "containers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "containers"."owner_player_id" IS 'Character the container belongs to.';
COMMENT ON COLUMN "containers"."kind" IS 'backpack | bag | bank | equipped | buyback | guild_bank. Equipped is modelled as a container so gear obeys the same one-item-one-place rule.';
COMMENT ON COLUMN "containers"."bag_slot" IS 'Which bag position this container occupies on the character. Zero for the backpack and the equipped set.';
COMMENT ON COLUMN "containers"."bag_item_instance_id" IS 'The bag item that provides the space. Null for the backpack, the bank and the equipped set, which exist without an item.';
COMMENT ON COLUMN "containers"."capacity" IS 'Number of usable positions. Copied from the bag template so resizing a bag design does not retroactively drop items on the floor.';
COMMENT ON COLUMN "containers"."created_at" IS 'When the container was opened or the bag equipped.';

CREATE UNIQUE INDEX "uq_containers_owner_kind_slot"
ON "containers" ("owner_player_id", "kind", "bag_slot");
CREATE UNIQUE INDEX "uq_containers_bag_item"
ON "containers" ("bag_item_instance_id");

CREATE TABLE IF NOT EXISTS "container_slots" (
	-- Container holding the item. Half of the composite primary key.
	"container_id" BIGINT,
	-- Zero-based slot index within the container. Half of the composite primary key, which is what makes drag-and-drop ordering stable.
	"position" SMALLINT,
	-- Item occupying the slot. Globally unique across the table, so an item is in exactly one place and duplication is impossible by constraint rather than by discipline.
	"item_instance_id" BIGINT NOT NULL UNIQUE,
	-- When the item landed here. Drives the recently-acquired highlight in the client.
	"placed_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("container_id", "position")
);

COMMENT ON TABLE "container_slots" IS 'The placement table. It carries no surrogate id on purpose: the composite key is the location, and the unique constraint on item_instance_id is the single strongest anti-duplication rule in the schema.';
COMMENT ON COLUMN "container_slots"."container_id" IS 'Container holding the item. Half of the composite primary key.';
COMMENT ON COLUMN "container_slots"."position" IS 'Zero-based slot index within the container. Half of the composite primary key, which is what makes drag-and-drop ordering stable.';
COMMENT ON COLUMN "container_slots"."item_instance_id" IS 'Item occupying the slot. Globally unique across the table, so an item is in exactly one place and duplication is impossible by constraint rather than by discipline.';
COMMENT ON COLUMN "container_slots"."placed_at" IS 'When the item landed here. Drives the recently-acquired highlight in the client.';

CREATE INDEX "idx_container_slots_item"
ON "container_slots" ("item_instance_id");

CREATE TABLE IF NOT EXISTS "trades" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Player who opened the trade window.
	"initiator_player_id" BIGINT NOT NULL,
	-- Player who accepted the invitation.
	"partner_player_id" BIGINT NOT NULL,
	-- open | confirmed | completed | cancelled | failed. Only completed trades moved items.
	"state" VARCHAR(24) NOT NULL DEFAULT 'open',
	-- Bumped on every change to either side of the offer. Both confirmations must quote the current revision, which is what stops the classic swap-at-the-last-moment scam.
	"revision" INTEGER NOT NULL DEFAULT 0,
	-- Revision the initiator agreed to. Null until they press accept.
	"initiator_confirmed_revision" INTEGER,
	-- Revision the partner agreed to. The trade executes only when both equal revision.
	"partner_confirmed_revision" INTEGER,
	-- When the window opened.
	"opened_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the swap committed or the window closed. Null while the trade is live.
	"settled_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "trades" IS 'A two-sided exchange. Confirmation is stored as a revision number rather than a boolean, so any edit to the offer invalidates both agreements instead of leaving a stale yes attached to different contents.';
COMMENT ON COLUMN "trades"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "trades"."initiator_player_id" IS 'Player who opened the trade window.';
COMMENT ON COLUMN "trades"."partner_player_id" IS 'Player who accepted the invitation.';
COMMENT ON COLUMN "trades"."state" IS 'open | confirmed | completed | cancelled | failed. Only completed trades moved items.';
COMMENT ON COLUMN "trades"."revision" IS 'Bumped on every change to either side of the offer. Both confirmations must quote the current revision, which is what stops the classic swap-at-the-last-moment scam.';
COMMENT ON COLUMN "trades"."initiator_confirmed_revision" IS 'Revision the initiator agreed to. Null until they press accept.';
COMMENT ON COLUMN "trades"."partner_confirmed_revision" IS 'Revision the partner agreed to. The trade executes only when both equal revision.';
COMMENT ON COLUMN "trades"."opened_at" IS 'When the window opened.';
COMMENT ON COLUMN "trades"."settled_at" IS 'When the swap committed or the window closed. Null while the trade is live.';

CREATE INDEX "idx_trades_initiator"
ON "trades" ("initiator_player_id", "opened_at");
CREATE INDEX "idx_trades_partner"
ON "trades" ("partner_player_id", "opened_at");

CREATE TABLE IF NOT EXISTS "trade_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Trade window the offer belongs to.
	"trade_id" BIGINT NOT NULL,
	-- Which side put the item up. Denormalised from the trade so one query renders both panes.
	"offering_player_id" BIGINT NOT NULL,
	-- Item staked. It stays owned by the offerer until the trade commits; only the commit rewrites container_slots.
	"item_instance_id" BIGINT NOT NULL,
	-- Units offered from the stack, which can be fewer than the instance holds when splitting a stack of materials.
	"stack_count" INTEGER NOT NULL DEFAULT 1,
	-- When the item was placed in the window.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "trade_items" IS 'Items staked on one side of a trade. The same instance cannot appear twice in a window, and the whole swap is a single transaction that rewrites container_slots for both players or rolls back entirely.';
COMMENT ON COLUMN "trade_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "trade_items"."trade_id" IS 'Trade window the offer belongs to.';
COMMENT ON COLUMN "trade_items"."offering_player_id" IS 'Which side put the item up. Denormalised from the trade so one query renders both panes.';
COMMENT ON COLUMN "trade_items"."item_instance_id" IS 'Item staked. It stays owned by the offerer until the trade commits; only the commit rewrites container_slots.';
COMMENT ON COLUMN "trade_items"."stack_count" IS 'Units offered from the stack, which can be fewer than the instance holds when splitting a stack of materials.';
COMMENT ON COLUMN "trade_items"."added_at" IS 'When the item was placed in the window.';

CREATE UNIQUE INDEX "uq_trade_items_trade_item"
ON "trade_items" ("trade_id", "item_instance_id");

CREATE TABLE IF NOT EXISTS "mail_messages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who sent it. Null for system mail from a quest, an auction house or a support action.
	"sender_player_id" BIGINT,
	-- Who receives it.
	"recipient_player_id" BIGINT NOT NULL,
	-- Subject line as typed.
	"subject" VARCHAR(120) NOT NULL,
	-- Message text. Null for pure item delivery.
	"body" TEXT,
	-- Currency travelling with the mail, in the smallest unit.
	"attached_copper" BIGINT NOT NULL DEFAULT 0,
	-- Cash on delivery. The recipient pays this before attachments unlock, which is how player-to-player commissions work without a trade window.
	"cod_copper" BIGINT NOT NULL DEFAULT 0,
	-- Send time. Mail is normally deliverable after a short hold.
	"sent_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When undelivered mail is returned to sender. Attachments are never silently deleted at this point.
	"expires_at" TIMESTAMP NOT NULL,
	-- First open. Null while unread.
	"read_at" TIMESTAMP,
	-- Set when the mail bounced back to the sender rather than being collected.
	"returned_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "mail_messages" IS 'Asynchronous delivery, and the only way to move an item to an offline player. Mail is also the escrow for the auction house, which is why attachments must survive expiry rather than being reaped with the message.';
COMMENT ON COLUMN "mail_messages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "mail_messages"."sender_player_id" IS 'Who sent it. Null for system mail from a quest, an auction house or a support action.';
COMMENT ON COLUMN "mail_messages"."recipient_player_id" IS 'Who receives it.';
COMMENT ON COLUMN "mail_messages"."subject" IS 'Subject line as typed.';
COMMENT ON COLUMN "mail_messages"."body" IS 'Message text. Null for pure item delivery.';
COMMENT ON COLUMN "mail_messages"."attached_copper" IS 'Currency travelling with the mail, in the smallest unit.';
COMMENT ON COLUMN "mail_messages"."cod_copper" IS 'Cash on delivery. The recipient pays this before attachments unlock, which is how player-to-player commissions work without a trade window.';
COMMENT ON COLUMN "mail_messages"."sent_at" IS 'Send time. Mail is normally deliverable after a short hold.';
COMMENT ON COLUMN "mail_messages"."expires_at" IS 'When undelivered mail is returned to sender. Attachments are never silently deleted at this point.';
COMMENT ON COLUMN "mail_messages"."read_at" IS 'First open. Null while unread.';
COMMENT ON COLUMN "mail_messages"."returned_at" IS 'Set when the mail bounced back to the sender rather than being collected.';

CREATE INDEX "idx_mail_recipient_sent"
ON "mail_messages" ("recipient_player_id", "sent_at");
CREATE INDEX "idx_mail_expires"
ON "mail_messages" ("expires_at");

CREATE TABLE IF NOT EXISTS "mail_attachments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Message carrying the item.
	"mail_id" BIGINT NOT NULL,
	-- Item in transit. Unique across the table so an item cannot be attached to two letters, which paired with container_slots keeps every item in exactly one place.
	"item_instance_id" BIGINT NOT NULL UNIQUE,
	-- Units attached from the stack.
	"stack_count" INTEGER NOT NULL DEFAULT 1,
	-- When the recipient pulled it out. Null while the item is still in the letter.
	"claimed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "mail_attachments" IS 'Items riding along with a message. While claimed_at is null the instance has no container slot and its owner_player_id is null, which is the in-transit state the audit log has to be able to explain.';
COMMENT ON COLUMN "mail_attachments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "mail_attachments"."mail_id" IS 'Message carrying the item.';
COMMENT ON COLUMN "mail_attachments"."item_instance_id" IS 'Item in transit. Unique across the table so an item cannot be attached to two letters, which paired with container_slots keeps every item in exactly one place.';
COMMENT ON COLUMN "mail_attachments"."stack_count" IS 'Units attached from the stack.';
COMMENT ON COLUMN "mail_attachments"."claimed_at" IS 'When the recipient pulled it out. Null while the item is still in the letter.';

CREATE INDEX "idx_mail_attachments_mail"
ON "mail_attachments" ("mail_id");

CREATE TABLE IF NOT EXISTS "item_events" (
	-- Surrogate primary key, and the total order of the log.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Item the event is about.
	"item_instance_id" BIGINT NOT NULL,
	-- created | looted | moved | equipped | traded | mailed | vendored | destroyed | restored | enchanted | repaired.
	"event_type" VARCHAR(32) NOT NULL,
	-- Who caused it. Null for server-driven events such as decay or a scheduled rollback.
	"actor_player_id" BIGINT,
	-- Previous owner for a transfer. Null when ownership did not change.
	"from_player_id" BIGINT,
	-- New owner for a transfer. Null when ownership did not change.
	"to_player_id" BIGINT,
	-- Container the item left. Null when it came from outside any container, such as a loot table.
	"from_container_id" BIGINT,
	-- Container the item entered. Null when it left the inventory entirely.
	"to_container_id" BIGINT,
	-- Change in stack size. Splits and merges are the events that make raw ownership snapshots lie.
	"stack_delta" INTEGER NOT NULL DEFAULT 0,
	-- trade | mail | quest | vendor | gm_action. Names the table reference_id points into.
	"reference_type" VARCHAR(24),
	-- Id within reference_type. Deliberately not a foreign key, because the log must outlive the rows it describes.
	"reference_id" BIGINT,
	-- Everything else worth keeping: coordinates, loot table id, durability before and after. Schemaless so a new event type needs no migration.
	"payload" JSONB,
	-- Server time of the event. The log is append-only and is the input to any rollback.
	"occurred_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "item_events" IS 'Append-only history of every item. It is the only table that can answer where did my sword go, and replaying it in reverse is how a duplication exploit gets rolled back without restoring an entire database.';
COMMENT ON COLUMN "item_events"."id" IS 'Surrogate primary key, and the total order of the log.';
COMMENT ON COLUMN "item_events"."item_instance_id" IS 'Item the event is about.';
COMMENT ON COLUMN "item_events"."event_type" IS 'created | looted | moved | equipped | traded | mailed | vendored | destroyed | restored | enchanted | repaired.';
COMMENT ON COLUMN "item_events"."actor_player_id" IS 'Who caused it. Null for server-driven events such as decay or a scheduled rollback.';
COMMENT ON COLUMN "item_events"."from_player_id" IS 'Previous owner for a transfer. Null when ownership did not change.';
COMMENT ON COLUMN "item_events"."to_player_id" IS 'New owner for a transfer. Null when ownership did not change.';
COMMENT ON COLUMN "item_events"."from_container_id" IS 'Container the item left. Null when it came from outside any container, such as a loot table.';
COMMENT ON COLUMN "item_events"."to_container_id" IS 'Container the item entered. Null when it left the inventory entirely.';
COMMENT ON COLUMN "item_events"."stack_delta" IS 'Change in stack size. Splits and merges are the events that make raw ownership snapshots lie.';
COMMENT ON COLUMN "item_events"."reference_type" IS 'trade | mail | quest | vendor | gm_action. Names the table reference_id points into.';
COMMENT ON COLUMN "item_events"."reference_id" IS 'Id within reference_type. Deliberately not a foreign key, because the log must outlive the rows it describes.';
COMMENT ON COLUMN "item_events"."payload" IS 'Everything else worth keeping: coordinates, loot table id, durability before and after. Schemaless so a new event type needs no migration.';
COMMENT ON COLUMN "item_events"."occurred_at" IS 'Server time of the event. The log is append-only and is the input to any rollback.';

CREATE INDEX "idx_item_events_instance_time"
ON "item_events" ("item_instance_id", "occurred_at");
CREATE INDEX "idx_item_events_actor_time"
ON "item_events" ("actor_player_id", "occurred_at");
CREATE INDEX "idx_item_events_type_time"
ON "item_events" ("event_type", "occurred_at");

